CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
CultureInfo.CurrentUICulture = CultureInfo.InvariantCulture;
if (args.Length != 1) throw new ArgumentException("Expected output fixture path.");
var json = new JsonSerializerOptions { WriteIndented = false, IncludeFields = true, NumberHandling = JsonNumberHandling.AllowNamedFloatingPointLiterals };
JsonElement Freeze(object? value) => JsonSerializer.SerializeToElement(value, json);

StarSystemState System(int id, float x = 0, float y = 0) => new(id, $"System {id}", new(x, y), StarArchetype.Standard, true, false, false, false, null, StellarPrimaryClass.GYellowDwarf, null, null, null, $"campaign-step:{id}");
PlanetaryBodyState Body(int id, int system, bool rare = false, double gravity = 1, bool legacyCandidate = true) => new(id, system, null, id, $"Body {id}", PlanetaryBodyKind.Planet, 1, 1, new(gravity, 288, 101.3, PlanetaryAtmosphereRegime.OxygenNitrogen, PlanetarySolventRegime.Water, .1, false, true), legacyCandidate, rare, false, false);
CivilizationState Civ(int id = 1, bool player = true, CivilizationDevelopmentStage stage = CivilizationDevelopmentStage.PreWarp, bool seededAncient = false) => new(id, $"Civ {id}", 0, CivilizationArchetype.Adaptive, CivilizationTraits.Balanced, player, stage, seededAncient, false, false, "terran_baseline") { Leadership = CivilizationLeadershipState.CreateFoundingRoster(id, player) };
ColonyState Colony(int id = 1, int system = 0, int civ = 1) => new() { Id = id, CivilizationId = civ, SystemId = system, PlanetaryBodyId = 10, Name = $"Colony {id}", PopulationSpeciesId = "terran_baseline", PopulationMillions = 1000, Infrastructure = 1.2, Stability = .92, StoredFoodPopulationDaysMillions = 100000, StoredWaterPopulationDaysMillions = 100000 };
FleetCombatState Combat(string profile = "patrol_corvette_mk1") => new() { ProfileId = profile, Shields = 35, Armor = 45, Hull = 95, Order = MilitaryOrderType.Hold };
FleetState Fleet(int id, int civ, FleetRole role, int? system = 0, double cargoCapacity = 0, double range = 500) => new() { Id = id, CivilizationId = civ, Name = $"Fleet {id}", Role = role, DesignId = cargoCapacity < 0 ? ShipDesignRegistry.ResourceOutpostShipId : role switch { FleetRole.Scout => "warp_scout", FleetRole.Science => "science_vessel", FleetRole.Colony => "colony_ship", FleetRole.Military => "patrol_corvette", _ => "bulk_freighter" }, Position = Vector2.Zero, CurrentSystemId = system, StrategicSpeed = 22, MaximumLegRangeLightYears = range, CargoMaterialCapacity = cargoCapacity, FuelCapacityLightYears = 1000, FuelRemainingLightYears = 900, SensorRange = 135, IsActive = true, Combat = Combat(role == FleetRole.Military ? "patrol_corvette_mk1" : "civilian_light_v1"), TacticalVessel = new MassiveVesselState { Id = id, Name = $"Fleet {id} vessel", DesignId = "history", IsFlagship = true, HullFraction = .9f, EngineFraction = .8f, SensorFraction = .7f, WarpDriveFraction = .6f, ReactorFraction = .5f, InterdictorFraction = .4f, BattlesFought = 3, ConfirmedKills = 2 } };
GalaxyState World(bool colony = false, bool player = true)
{
    var civs = new List<CivilizationState> { Civ(player: player) };
    return new GalaxyState { Seed = 38001, Systems = new List<StarSystemState> { System(0), System(1, 4), System(2, 8) }, PlanetaryBodies = new List<PlanetaryBodyState> { Body(10, 0), Body(20, 1, true), Body(30, 1, true, 10), Body(35, 1), Body(40, 2, true, 10, false) }, Civilizations = civs, Fleets = new List<FleetState>(), Colonies = colony ? new List<ColonyState> { Colony() } : new List<ColonyState>(), Economies = new List<CivilizationEconomyState> { new() { CivilizationId = 1, Credits = 500, Industry = 200, Science = 0 } }, Technologies = new TechnologySeeder().Seed(civs), ConstructionStates = new ConstructionSeeder().Seed(civs), ShipyardStates = new ShipyardSeeder().Seed(civs), PlayerCivilizationId = 1, Knowledge = new CivilizationKnowledgeState() };
}
object Snapshot(GalaxyState g) => new { g.Seed, g.Systems, Bodies = g.PlanetaryBodies, g.Civilizations, g.Fleets, g.Colonies, g.Economies, g.Technologies, Construction = g.ConstructionStates, Shipyards = g.ShipyardStates, g.PlayerCivilizationId, Knowledge = new { CoreObservers = g.Knowledge.GetGalacticCoreObservers(), Observers = g.Civilizations.Select(c => new { CivilizationId = c.Id, HasCoreAccess = g.Knowledge.HasGalacticCoreAccess(c.Id), CoreDiscovered = g.Knowledge.IsGalacticCoreDiscovered(c.Id), KnownSystems = g.Knowledge.GetKnownSystems(c.Id), KnownCivilizations = g.Knowledge.GetKnownCivilizations(c.Id), Survey = g.Knowledge.GetSystemSurveyKnowledge(c.Id) }).ToArray() }, Core = g.GalacticCore };

var cases=new List<object>();
void Scenario(string name,bool raw,Action<GalaxyState,GalaxySimulationStepCoordinator,List<object>> body){var g=World(colony:true);var callbackCalls=new List<object>();ICombatHostilityView hostility=name=="raw-batch-partial-exception"?new ThrowSecondHostility(callbackCalls):new AlwaysHostile(callbackCalls);var coordinator=raw?new GalaxySimulationStepCoordinator(combat:new CombatSimulation(hostility)):new GalaxySimulationStepCoordinator(combatRuntime:new CombatCommandRuntime(hostility));var commands=new List<object>();body(g,coordinator,commands);cases.Add(new{Name=name,Mode=raw?"Raw":"Matched",Controls=new{ThrowHostilityCall=name=="raw-batch-partial-exception"?2:0},Commands=commands,CallbackCalls=Freeze(callbackCalls.ToArray())});}
void Run<T>(List<object> rows,GalaxyState g,string op,object input,Func<T> invoke){var frozenInput=Freeze(input);var before=Freeze(Snapshot(g));T? typed=default;Exception? caught=null;try{typed=invoke();}catch(Exception e){caught=e;}var result=caught is null?Freeze(typed):(JsonElement?)null;var error=caught is null?(JsonElement?)null:Freeze(new{Type=caught.GetType().Name,caught.Message});rows.Add(new{Op=op,Input=frozenInput,Result=result,Error=error,Before=before,After=Freeze(Snapshot(g))});}
void SetupCombat(GalaxyState g){g.Civilizations.Add(Civ(2,false,CivilizationDevelopmentStage.WarpCapable));var a=Fleet(9,1,FleetRole.Military);var b=Fleet(2,1,FleetRole.Military);var enemy=Fleet(7,2,FleetRole.Military);g.Fleets.Add(a);g.Fleets.Add(enemy);g.Fleets.Add(b);}
Scenario("matched-combat-sequence",false,(g,c,r)=>{SetupCombat(g);Run(r,g,"IssueMilitaryOrder",new{CivilizationId=1,FleetId=9,Order=new MilitaryOrder(MilitaryOrderType.Hold)},()=>c.IssueMilitaryOrder(g,1,9,new(MilitaryOrderType.Hold)));Run(r,g,"PreviewMilitaryOrders",new{CivilizationId=1,FleetIds=new[]{9,2,9},Order=new MilitaryOrder(MilitaryOrderType.Hold)},()=>c.PreviewMilitaryOrders(g,1,new[]{9,2,9},new(MilitaryOrderType.Hold)));Run(r,g,"PreviewMilitaryOrder",new{CivilizationId=1,FleetId=9,Order=new MilitaryOrder(MilitaryOrderType.Hold)},()=>c.PreviewMilitaryOrder(g,1,9,new(MilitaryOrderType.Hold)));Run(r,g,"IssueMilitaryOrders",new{CivilizationId=1,FleetIds=new[]{99,9,2,9},Order=new MilitaryOrder(MilitaryOrderType.Hold)},()=>c.IssueMilitaryOrders(g,1,new[]{99,9,2,9},new(MilitaryOrderType.Hold)));Run(r,g,"IssueEngageHostilesOrder",new{CivilizationId=1,FleetId=9},()=>c.IssueEngageHostilesOrder(g,1,9));Run(r,g,"ForceSummary",new{CivilizationId=1},()=>c.GetOwnMilitaryForceSummary(g,1));Run(r,g,"Readiness",new{CivilizationId=1},()=>c.GetOwnCombatReadinessSummary(g,1));Run(r,g,"ReadinessUnknown",new{CivilizationId=99},()=>c.GetOwnCombatReadinessSummary(g,99));Run(r,g,"FleetStatus",new{CivilizationId=1},()=>c.GetOwnCombatFleetStatus(g,1));});
Scenario("raw-combat-ordering",true,(g,c,r)=>{SetupCombat(g);Run(r,g,"IssueMilitaryOrders",new{CivilizationId=1,FleetIds=new[]{99,9,2,9},Order=new MilitaryOrder(MilitaryOrderType.Hold)},()=>c.IssueMilitaryOrders(g,1,new[]{99,9,2,9},new(MilitaryOrderType.Hold)));Run(r,g,"IssueEngageHostilesOrder",new{CivilizationId=1,FleetId=9},()=>c.IssueEngageHostilesOrder(g,1,9));Run(r,g,"PreviewMilitaryOrder",new{CivilizationId=1,FleetId=9,Order=new MilitaryOrder(MilitaryOrderType.Hold)},()=>c.PreviewMilitaryOrder(g,1,9,new(MilitaryOrderType.Hold)));});
Scenario("raw-batch-partial-exception",true,(g,c,r)=>{SetupCombat(g);Run(r,g,"IssueMilitaryOrders",new{CivilizationId=1,FleetIds=new[]{9,2},Order=new MilitaryOrder(MilitaryOrderType.Attack,7)},()=>c.IssueMilitaryOrders(g,1,new[]{9,2},new(MilitaryOrderType.Attack,7)));Run(r,g,"IssueMilitaryOrderRetry",new{CivilizationId=1,FleetId=9,Order=new MilitaryOrder(MilitaryOrderType.Hold)},()=>c.IssueMilitaryOrder(g,1,9,new(MilitaryOrderType.Hold)));});
Scenario("deployment-duplicate-reresolve",false,(g,c,r)=>{SetupCombat(g);g.Fleets.Insert(0,Fleet(9,2,FleetRole.Scout));Run(r,g,"DeployDuplicateReresolve",new{CivilizationId=1,FleetId=9,DestinationSystemId=1},()=>c.IssueMilitaryDeploymentOrder(g,1,9,1));});Scenario("deployment-unsupported",false,(g,c,r)=>{SetupCombat(g);((List<FleetState>)g.Fleets).RemoveAll(x=>x.Id==9);g.Fleets.Add(Fleet(9,1,FleetRole.Military,range:.01));Run(r,g,"DeployUnsupported",new{CivilizationId=1,FleetId=9,DestinationSystemId=1},()=>c.IssueMilitaryDeploymentOrder(g,1,9,1));});Scenario("deployment-guards-and-success",false,(g,c,r)=>{SetupCombat(g);var inactive=Fleet(10,1,FleetRole.Military);inactive.IsActive=false;g.Fleets.Add(inactive);g.Fleets.Add(Fleet(11,2,FleetRole.Military));g.Fleets.Add(Fleet(12,1,FleetRole.Scout));Run(r,g,"DeployInactive",new{CivilizationId=1,FleetId=10,DestinationSystemId=1},()=>c.IssueMilitaryDeploymentOrder(g,1,10,1));Run(r,g,"DeployForeign",new{CivilizationId=1,FleetId=11,DestinationSystemId=1},()=>c.IssueMilitaryDeploymentOrder(g,1,11,1));Run(r,g,"DeployWrongRole",new{CivilizationId=1,FleetId=12,DestinationSystemId=1},()=>c.IssueMilitaryDeploymentOrder(g,1,12,1));Run(r,g,"DeployMissingFleet",new{CivilizationId=1,FleetId=99,DestinationSystemId=1},()=>c.IssueMilitaryDeploymentOrder(g,1,99,1));Run(r,g,"DeployMissingSystem",new{CivilizationId=1,FleetId=9,DestinationSystemId=99},()=>c.IssueMilitaryDeploymentOrder(g,1,9,99));Run(r,g,"DeployAlreadyThere",new{CivilizationId=1,FleetId=9,DestinationSystemId=0},()=>c.IssueMilitaryDeploymentOrder(g,1,9,0));Run(r,g,"Deploy",new{CivilizationId=1,FleetId=9,DestinationSystemId=1},()=>c.IssueMilitaryDeploymentOrder(g,1,9,1));});
Scenario("colony-outpost-filtering",false,(g,c,r)=>{var colony=Fleet(20,1,FleetRole.Colony);colony.EmbarkedPopulationMillions=double.NaN;colony.EmbarkedPopulationSpeciesId="terran_baseline";g.Fleets.Add(colony);var outpost=Fleet(21,1,FleetRole.Colony,cargoCapacity:-1);outpost.EmbarkedPopulationMillions=2;outpost.EmbarkedPopulationSpeciesId="terran_baseline";g.Fleets.Add(outpost);var inactiveColony=Fleet(22,1,FleetRole.Colony);inactiveColony.IsActive=false;inactiveColony.EmbarkedPopulationMillions=2;g.Fleets.Add(inactiveColony);var foreignColony=Fleet(23,2,FleetRole.Colony);foreignColony.EmbarkedPopulationMillions=2;g.Fleets.Add(foreignColony);var wrongRole=Fleet(24,1,FleetRole.Scout);wrongRole.EmbarkedPopulationMillions=2;g.Fleets.Add(wrongRole);var zero=Fleet(25,1,FleetRole.Colony);zero.EmbarkedPopulationMillions=0;g.Fleets.Add(zero);var noSpecies=Fleet(26,1,FleetRole.Colony);noSpecies.EmbarkedPopulationMillions=2;noSpecies.EmbarkedPopulationSpeciesId=null;g.Fleets.Add(noSpecies);var valid=Fleet(27,1,FleetRole.Colony);valid.EmbarkedPopulationMillions=4;valid.EmbarkedPopulationSpeciesId="terran_baseline";g.Fleets.Add(valid);g.Knowledge.MarkSystemFullySurveyed(1,1);g.Knowledge.MarkSystemFullySurveyed(1,2);Run(r,g,"ColonyPlan",new{FleetId=27,MaximumCandidates=3},()=>c.GetColonyOpportunityPlan(g,27,3));Run(r,g,"OutpostPlan",new{FleetId=21,MaximumCandidates=4},()=>c.GetResourceOutpostOpportunityPlan(g,21,4));Run(r,g,"IssueColonyFleetOrder",new{ActingCivilizationId=1,FleetId=27,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueColonyFleetOrder(g,1,27,1,20));Run(r,g,"IssueOutpost",new{ActingCivilizationId=1,FleetId=21,DestinationSystemId=2,PlanetaryBodyId=40},()=>c.IssueResourceOutpostFleetOrder(g,1,21,2,40));Run(r,g,"IssueColonyFleetOrder",new{ActingCivilizationId=1,FleetId=22,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueColonyFleetOrder(g,1,22,1,20));Run(r,g,"IssueColonyFleetOrder",new{ActingCivilizationId=1,FleetId=23,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueColonyFleetOrder(g,1,23,1,20));Run(r,g,"IssueColonyFleetOrder",new{ActingCivilizationId=1,FleetId=24,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueColonyFleetOrder(g,1,24,1,20));Run(r,g,"IssueColonyFleetOrder",new{ActingCivilizationId=1,FleetId=25,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueColonyFleetOrder(g,1,25,1,20));Run(r,g,"IssueColonyFleetOrder",new{ActingCivilizationId=1,FleetId=26,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueColonyFleetOrder(g,1,26,1,20));Run(r,g,"ColonyPlan",new{FleetId=20,MaximumCandidates=3},()=>c.GetColonyOpportunityPlan(g,20,3));Run(r,g,"IssueColonyFleetOrder",new{ActingCivilizationId=1,FleetId=20,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueColonyFleetOrder(g,1,20,1,20));Run(r,g,"OutpostPlan",new{FleetId=21,MaximumCandidates=4},()=>c.GetResourceOutpostOpportunityPlan(g,21,4));Run(r,g,"IssueOutpost",new{ActingCivilizationId=2,FleetId=21,DestinationSystemId=1,PlanetaryBodyId=20},()=>c.IssueResourceOutpostFleetOrder(g,2,21,1,20));});
Scenario("freight-and-civilian-sequence",false,(g,c,r)=>{var f=Fleet(30,1,FleetRole.Logistics,0,100);f.CargoMaterials=10;g.Fleets.Add(f);var civilian=Fleet(31,1,FleetRole.Colony);civilian.EmbarkedPopulationMillions=3;civilian.EmbarkedPopulationSpeciesId="terran_baseline";g.Fleets.Add(civilian);Run(r,g,"FreightCollection",new{ActingCivilizationId=1,FleetId=30,OutpostId=999},()=>c.IssueFreightCollectionOrder(g,1,30,999));Run(r,g,"FreightTransit",new{ActingCivilizationId=1,FleetId=30,TargetSystemId=1},()=>c.IssueFreightTransitOrder(g,1,30,1));Run(r,g,"CivilianHold",new{ActingCivilizationId=1,FleetId=31},()=>c.IssueCivilianHoldOrder(g,1,31));Run(r,g,"CivilianResume",new{ActingCivilizationId=1,FleetId=31},()=>c.IssueCivilianResumeOrder(g,1,31));Run(r,g,"PreviewReturn",new{ActingCivilizationId=1,FleetId=31},()=>c.PreviewCivilianReturnToBase(g,1,31));Run(r,g,"RequestReturn",new{ActingCivilizationId=1,FleetId=31,Confirm=false},()=>c.IssueCivilianReturnToBaseOrder(g,1,31,false));});
var rawNull=new GalaxySimulationStepCoordinator(combat:new CombatSimulation());CombatOrderResult? engageNull=null;Exception? engageError=null;try{engageNull=rawNull.IssueEngageHostilesOrder(null!,1,1);}catch(Exception e){engageError=e;}CombatOrderPreview? previewNull=null;Exception? previewError=null;try{previewNull=rawNull.PreviewMilitaryOrder(null!,1,1,new(MilitaryOrderType.Hold));}catch(Exception e){previewError=e;}var nullOrdering=new[]{new{Name="RawEngageNull",Result=engageNull is null?(JsonElement?)null:Freeze(engageNull),Error=engageError is null?(JsonElement?)null:Freeze(new{Type=engageError.GetType().Name,engageError.Message})},new{Name="RawPreviewNull",Result=previewNull is null?(JsonElement?)null:Freeze(previewNull),Error=previewError is null?(JsonElement?)null:Freeze(new{Type=previewError.GetType().Name,previewError.Message})}};File.WriteAllText(args[0],JsonSerializer.Serialize(new{Schema="stellar-campaign-command-oracle-v1",Culture="InvariantCulture",Cases=cases,ScenarioCount=cases.Count,CommandCount=cases.Sum(x=>JsonSerializer.SerializeToElement(x).GetProperty("Commands").GetArrayLength()),NullOrdering=nullOrdering},json)+Environment.NewLine);Console.WriteLine($"campaign command oracle: {cases.Count} scenarios");
sealed class AlwaysHostile(List<object> calls):ICombatHostilityView{public bool AreHostile(int first,int second){calls.Add(new{First=first,Second=second});return true;}} sealed class ThrowSecondHostility(List<object> log):ICombatHostilityView{int calls;public bool AreHostile(int first,int second){log.Add(new{First=first,Second=second});if(++calls==2)throw new InvalidOperationException("fixture hostility failure");return true;}}
